const ACCEPTANCE_RUN_LOCK_INIT_GRACE_MS = 30_000;
const acceptanceTrackedResponses = new Map();
let acceptanceResponseSequence = 0;
function acceptanceTrackedFetch(originalFetch) {
  return async function trackedAcceptanceFetch(input, init = {}) {
    let responsePath = '';
    try {
      responsePath = new URL(input?.url || input || '', 'http://127.0.0.1').pathname;
    } catch {
      responsePath = '<invalid-url>';
    }
    const method = String(init?.method || input?.method || 'GET').toUpperCase();
    const response = await originalFetch(input, init);
    return acceptanceTrackResponse(response, { method, path: responsePath });
  };
}

function acceptanceTrackResponse(response, { method = '', path: responsePath = '' } = {}) {
  const id = ++acceptanceResponseSequence;
  const record = { id, method, path: responsePath, response, release: '' };
  acceptanceTrackedResponses.set(id, record);
  const markReleased = reason => {
    if (!record.release) record.release = reason;
  };
  const wrapReader = reader => {
    if (!reader || typeof reader !== 'object') return reader;
    return new Proxy(reader, {
      get(target, property, receiver) {
        if (property === 'cancel' && typeof target.cancel === 'function') {
          return (...args) => {
            const pending = Reflect.apply(target.cancel, target, args);
            return Promise.resolve(pending).then(value => {
              markReleased('reader.cancel');
              return value;
            });
          };
        }
        if (property === 'read' && typeof target.read === 'function') {
          return (...args) => Promise.resolve(Reflect.apply(target.read, target, args)).then(result => {
            if (result?.done) markReleased('reader.done');
            return result;
          });
        }
        return Reflect.get(target, property, target);
      },
    });
  };
  const wrapBody = body => {
    if (!body || typeof body !== 'object') return body;
    return new Proxy(body, {
      get(target, property, receiver) {
        if (property === 'cancel' && typeof target.cancel === 'function') {
          return (...args) => {
            const pending = Reflect.apply(target.cancel, target, args);
            return Promise.resolve(pending).then(value => {
              markReleased('body.cancel');
              return value;
            });
          };
        }
        if (property === 'getReader' && typeof target.getReader === 'function') {
          return (...args) => wrapReader(Reflect.apply(target.getReader, target, args));
        }
        return Reflect.get(target, property, target);
      },
    });
  };
  return new Proxy(response, {
    get(target, property, receiver) {
      if (['arrayBuffer', 'blob', 'formData', 'json', 'text'].includes(property)
        && typeof target[property] === 'function') {
        return (...args) => {
          const pending = Reflect.apply(target[property], target, args);
          return Promise.resolve(pending).then(value => {
            markReleased(property);
            return value;
          }, error => {
            if (target.bodyUsed) markReleased(`${property}:body_used`);
            throw error;
          });
        };
      }
      if (property === 'body') return wrapBody(target.body);
      return Reflect.get(target, property, target);
    },
  });
}

function acceptanceUnreleasedResponses() {
  const pending = [];
  for (const record of acceptanceTrackedResponses.values()) {
    if (record.release) continue;
    if (record.response.bodyUsed) {
      record.release = 'body_used';
      continue;
    }
    if (!record.response.body) {
      record.release = 'no_body';
      continue;
    }
    pending.push(record);
  }
  return pending;
}

async function releaseAcceptanceResponses() {
  const pending = acceptanceUnreleasedResponses();
  const cleanupErrors = [];
  for (const record of pending) {
    try {
      const body = record.response.body;
      if (typeof body?.cancel !== 'function') throw new Error('loopback response body has no cancel owner');
      await body.cancel();
      if (!record.release) record.release = 'body.cancel';
    } catch (error) {
      cleanupErrors.push({ record, error });
    }
  }
  const remaining = acceptanceUnreleasedResponses();
  if (cleanupErrors.length || remaining.length) {
    const error = new Error(`loopback response owners were not released; remaining=${remaining.map(item => `${item.method} ${item.path}`).join(', ')}`);
    error.cause = cleanupErrors[0]?.error;
    error.cleanup_errors = cleanupErrors.map(item => ({
      method: item.record.method,
      path: item.record.path,
      message: String(item.error?.message || item.error),
    }));
    throw error;
  }
  return pending.length;
}

function assertAcceptanceResponsesReleased(label = 'loopback') {
  const pending = acceptanceUnreleasedResponses();
  assert.equal(pending.length, 0, `${label} left unconsumed response owners: ${pending.map(item => `${item.method} ${item.path}`).join(', ')}`);
}

async function consumeAcceptanceResponse(response) {
  if (!response || response.bodyUsed) return response;
  try {
    await response.arrayBuffer();
  } catch {}
  return response;
}

async function assertAcceptanceStatus(response, expected, message) {
  try {
    assert.equal(response?.status, expected, message);
  } finally {
    await consumeAcceptanceResponse(response);
  }
  return response;
}

