async function listenLocalTestServer(server) {
  for (let attempt = 0; attempt < 60; attempt++) {
    const port = 31000 + crypto.randomInt(0, 30000);
    try {
      await new Promise((resolve, reject) => {
        const onError = (error) => {
          server.off('listening', onListening);
          reject(error);
        };
        const onListening = () => {
          server.off('error', onError);
          resolve();
        };
        server.once('error', onError);
        server.once('listening', onListening);
        server.listen(port, '127.0.0.1');
      });
      return port;
    } catch (e) {
      if (!isLoopbackPortUnavailableError(e)) throw e;
    }
  }
  throw new Error('no safe local test port available');
}

