    assert.equal(await fsp.readFile(path.join(targetRoot, 'db_storage', 'message', 'message_0.db'), 'utf-8'), 'stable-indexed-generation', 'strict manifest recovery should restore the uniquely indexed previous generation');
    await assert.rejects(() => fsp.stat(path.join(targetRoot, 'db_storage', 'message', 'message_1.db')), error => error?.code === 'ENOENT', 'strict manifest recovery must remove uncommitted database files from the exposed target');

    const scopedOnlyTargetFile = path.join(targetRoot, 'db_storage', 'message', 'message_0.db');
