    assert.equal(await fsp.readFile(scopedOnlyTargetFile, 'utf-8'), 'stable-indexed-generation', 'an ambiguous current target must remain untouched until a complete replacement is committed');
    assert.equal(await fsp.readFile(path.join(scopedOnlyPrevious, 'db_storage', 'contact', 'contact.db'), 'utf-8'), 'unique-uncovered-category', 'an uncovered previous category must not be deleted merely because the source path currently exists');

    await fsp.rm(scopedOnlyPrevious, { recursive: true, force: true });
