async function verifyMacOSPlatformSupport() {
  console.log('verifyMacOSPlatformSupport');
  if (process.platform !== 'darwin') {
    console.log(`  ⊘ macOS 平台验收跳过（当前为 ${process.platform}）`);
    return;
  }

  console.log(`  检查 macOS Node 架构（当前 ${process.arch}）...`);
  assert.ok(['arm64', 'x64'].includes(process.arch), `macOS Node 架构必须是 arm64 或 x64，当前为 ${process.arch}`);

  console.log('  检查 macOS 启动脚本...');
  const launchPath = path.join(ROOT, '启动.command');
  await fsp.access(launchPath);
  const launchStat = await fsp.stat(launchPath);
  assert.notEqual(launchStat.mode & 0o111, 0, '启动.command 必须可执行（chmod +x）');
  const launchContent = await fsp.readFile(launchPath, 'utf-8');
  await runCommand('sh', ['-n', './启动.command']);
  assert.ok(launchContent.includes('#!/usr/bin/env bash'), '启动.command 必须是 bash 脚本');
  assert.ok(
    launchContent.includes('command -v node')
      && launchContent.includes('NODE_MAJOR')
      && launchContent.includes("process.versions.node.split('.')[0]")
      && launchContent.includes('Node.js 20+')
      && launchContent.includes('请升级到 Node.js 20+'),
    '启动.command 必须检查 Node.js 20+ 并给出可读升级提示',
  );
  assert.ok(launchContent.includes('node src/main.js'), '启动.command 必须启动 main.js');
  assert.ok(launchContent.includes('scripts/check-dependencies.mjs') && launchContent.includes('npm ci'), '启动.command 必须自动修复缺失、过期或 ABI 不兼容的依赖');
  assert.ok(launchContent.includes('.nvm/nvm.sh') && launchContent.includes('.asdf/asdf.sh'), '启动.command 应兼容常见 macOS Node 安装路径');
  assert.ok(
    launchContent.includes('/opt/homebrew/bin')
      && launchContent.includes('/usr/local/bin')
      && launchContent.includes('/opt/homebrew/opt/node@24/bin')
      && launchContent.includes('/usr/local/opt/node@24/bin')
      && launchContent.includes('/opt/homebrew/opt/node@22/bin')
      && launchContent.includes('/usr/local/opt/node@22/bin')
      && launchContent.includes('/opt/homebrew/opt/node@20/bin')
      && launchContent.includes('/usr/local/opt/node@20/bin'),
    '启动.command 必须补齐 Homebrew 常见 PATH 和版本化 Node LTS keg-only 路径',
  );
  assert.ok(launchContent.includes('corepack npm ci'), '启动.command 必须在 npm 不在 PATH 时使用 corepack fallback');
  assert.match(launchContent, /set \+u[\s\S]*\.nvm\/nvm\.sh[\s\S]*\.asdf\/asdf\.sh[\s\S]*set -u/, '启动.command source nvm/asdf 时必须暂时关闭 nounset');

  console.log('  检查 macOS 微信进程探测...');
  let env = null;
  const discoveryController = new AbortController();
  const discoveryTimeout = setTimeout(() => {
    discoveryController.abort(Object.assign(new Error('macOS 微信进程探测超过 15 秒'), { name: 'AbortError', status: 499 }));
  }, 15000);
  try {
    env = await discoverWeixinEnvironment({ signal: discoveryController.signal });
  } catch (e) {
    const message = String(e?.message || e || '');
    if (!/未检测到|not found/i.test(message)) throw e;
    env = { running: false, processes: [], accounts: [], message };
  } finally {
    clearTimeout(discoveryTimeout);
  }
  assert.ok(env && typeof env === 'object', 'macOS 微信进程探测必须返回结构化结果');
  assert.equal(typeof env.running, 'boolean', 'macOS 微信进程探测必须返回 running 布尔值');
  assert.ok(Array.isArray(env.processes), 'macOS 微信进程探测必须返回进程数组');
  assert.ok(Array.isArray(env.accounts), 'macOS 微信进程探测必须返回账号数组');
  assert.equal(typeof env.message, 'string', 'macOS 微信进程探测必须返回可读提示');
  if (!env.running) {
    assert.match(env.message, /Mac 微信|WeChat|微信 v4 数据目录|未检测到|not found/i, 'macOS 未检测到微信时必须给出可读提示');
  }
  console.log('  ✓ macOS 平台基础支持验证通过');
}

async function verifyMacOSKeychain() {
  console.log('verifyMacOSKeychain');
  if (process.platform !== 'darwin') {
    console.log('  ⊘ macOS Keychain 验收跳过');
    return;
  }

  console.log('  检查 macOS Keychain 包装密钥 + data/secrets.bin 加密包...');
  const testSecret = `test-secret-${crypto.randomBytes(16).toString('hex')}`;
  const encrypted = await protectText(testSecret);
  assert.ok(Buffer.isBuffer(encrypted), 'macOS protectText 应返回加密 envelope Buffer');
  const envelope = JSON.parse(encrypted.toString('utf-8'));
  assert.equal(envelope.platform, 'darwin-keychain', 'macOS 必须使用 Keychain envelope');
  assert.equal(envelope.version, 1, 'Keychain envelope 版本必须匹配当前实现');
  assert.equal(envelope.alg, 'aes-256-gcm', 'Keychain envelope 必须使用 AES-256-GCM');
  assert.equal(typeof envelope.data, 'string', '加密 data 必须存在');
  assert.equal(typeof envelope.iv, 'string', 'iv 必须存在');
  assert.equal(typeof envelope.tag, 'string', 'auth tag 必须存在');
  assert.equal(await unprotectToText(encrypted), testSecret, 'Keychain 加密解密必须可逆');
  await assert.rejects(
    unprotectToText(Buffer.from(JSON.stringify({ ...envelope, platform: 'unknown' }), 'utf-8')),
    /unsupported macOS secret envelope/,
    '错误的 macOS envelope 必须被拒绝',
  );
  console.log('  ✓ macOS Keychain 包装密钥加密验证通过');
}

