  assert.ok(installer.includes('chmodSync(hook, 0o755)'), 'hook installer should restore executable permission on macOS/Linux');
  assert.equal(await gitConfigGet('core.hooksPath'), '.githooks', 'current repository should have the pre-commit hook enabled');

  const gitignore = await fsp.readFile(path.join(ROOT, '.gitignore'), 'utf-8');
