    assert.equal(manualKeyVerifiedForAccount(verifiedManualSettings, 'wxacc_test_manual', ['legacy_manual'], manualAccountFingerprint), true, 'public settings should expose enough verified-account fingerprint state for /api/state and the frontend to unblock the current account after validation');
    assert.equal(manualKeyVerifiedForAccount(verifiedManualSettings, 'legacy_manual', ['wxacc_test_manual'], manualAccountFingerprint), false, 'manual-key verification must not be accepted through a legacy alias that could collide with another account');
