  assert.match(bundle.text, /链接打开结果[\s\S]*页面标题 sk-\[redacted\]/, 'formatted prompt should use redacted link preview titles');

  const windowsDbPath = 'C:\\Users\\me\\Documents\\xwechat_files\\wxid_abc\\db_storage\\message\\message_0.db';
  const windowsForwardSlashDbPath = 'C:/Users/me/Documents/xwechat_files/wxid_abc/db_storage/message/message_2.db';
