  const pathsSourceForDisk = normalizeSourceText(await fsp.readFile(path.join(ROOT, 'src', 'lib', 'paths.js'), 'utf-8'));
  const discoverySourceForDisk = normalizeSourceText(await fsp.readFile(path.join(ROOT, 'src', 'wxenv', 'discovery.js'), 'utf-8'));
  const thumbnailSource = normalizeSourceText(await fsp.readFile(path.join(ROOT, 'src', 'renderer', 'thumbnail.js'), 'utf-8'));
